(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const sx1 = x+w1x, sy1 = y+w1y;
  const w2x = Math.sin(sx1*0.012-t*0.15)*8+Math.cos(sy1*0.01+t*0.18)*6;
  const w2y = Math.cos(sy1*0.013+t*0.12)*8+Math.sin(sx1*0.011-t*0.2)*6;
  const sx = sx1+w2x, sy = sy1+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,1.0],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,2.0],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,3.0],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,4.0],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,5.0],
    [80+Math.sin(t*0.45+1)*70,40+Math.cos(t*0.65+2)*50,0.11,2.1,0.5],
    [400+Math.cos(t*0.55+3)*60,220+Math.sin(t*0.75+1)*40,0.085,2.4,3.5]
  ];
  let aS=0,iS=0,cS=0;
  for(const[sX,sY,f,sp,ph]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const w=Math.sin(d*0.02-t*0.5)*0.15+1;
    aS+=Math.sin(d*f-t*sp+ph)*w;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5+ph)*w;
    cS+=Math.sin(d*f*1.3-t*sp*0.4+ph+2)*w*0.5;
  }
  const act=aS/8,inh=iS/8,cpl=cS/8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2
    +Math.sin(sx*0.07*Math.cos(t*0.1)+sy*0.05*Math.sin(t*0.15)+t*0.6)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    +Math.sin(dist*0.03-ang*7+t*0.8)*0.2+Math.sin(dist*0.065+ang*2-t*2.1)*0.15;
  const micro=(Math.sin(sx*0.3+t*1.5)*Math.sin(sy*0.3-t*1.2)+Math.sin((sx-sy)*0.2+t*0.9))*0.12;
  const rd1=Math.tanh((act-inh*0.65+bg*0.3+spiral)*2.2);
  const rd2=Math.tanh((cpl-act*0.5+inh*0.3+micro)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const pulse=0.95+Math.sin(t*0.4)*0.05;
  const blend=rd1*0.55+rd2*0.2+cell*0.15+micro*0.1;
  const v=Math.tanh(blend*1.8)*pulse*0.5+0.5;
  const pal=[
    [5,10,42],[12,35,85],[18,75,120],[25,130,130],[45,170,120],
    [140,190,90],[210,190,70],[220,155,65],[200,110,65],[175,65,60],
    [130,40,55],[85,25,50],[45,18,48],[5,10,42]
  ];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.8+Math.sin(rd1*Math.PI)*0.2;
  const edge=Math.abs(rd1)>0.65?1.12:1.0;
  const highlight=Math.max(0,rd2*0.15);
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+highlight*255)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+highlight*180)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+highlight*80)|0
  ];
}
